$(function () {
	var revealSelectors = [
		'.hero-copy',
		'.hero-art',
		'.section-heading',
		'.workflow-card',
		'.audience-intro',
		'.audience-item',
		'.account-notice',
		'.setup-intro',
		'.step',
		'.project-grid > div',
		'.safety-grid > div'
	];
	var $revealElements = $(revealSelectors.join(', '));
	var reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

	$revealElements.addClass('reveal');

	$revealElements.each(function (index) {
		var delay = $(this).index() * 80;
		$(this).css('--reveal-delay', reducedMotion ? '0ms' : delay + 'ms');
	});

	function updateRevealState() {
		var windowTop = $(window).scrollTop();
		var windowBottom = windowTop + $(window).height();

		$revealElements.each(function () {
			var $element = $(this);
			var elementTop = $element.offset().top;
			var isVisible = elementTop < windowBottom - 60 && elementTop > windowTop - $element.outerHeight();

			$element.toggleClass('is-visible', reducedMotion || isVisible);
		});
	}

	$(window).on('scroll resize', updateRevealState);
	updateRevealState();
});
